cat > bot.mjs <<'EOF'
import path from "node:path";
import os from "node:os";

export const REASON_CODES = [
  "sent",
  "already_handled",
  "new_user_no_suggestions",
  "daily_nudge_cap_reached",
  "unknown_timezone",
  "unknown_cap",
  "unknown_user_data",
  "unknown_candidate",
];

// Numbers chosen: new users get no inferred suggestions for 3 days.
const NEW_USER_MS = 3 * 24 * 3600 * 1000;

const hold = (reasonCode) => ({ send: false, reasonCode });

export async function decide({ user, candidate, now, config } = {}) {
  const dir = process.env.STATE_DIR || path.join(os.tmpdir(), "bot-state");
  if (!user || !user.id || !candidate || candidate.id == null) return hold("unknown_candidate");
  const origin = candidate.origin;
  if (!["requested", "inferred", "reminder"].includes(origin)) return hold("unknown_candidate");
  const nowMs = now instanceof Date ? now.getTime() : new Date(now).getTime();
  if (!Number.isFinite(nowMs)) return hold("unknown_user_data");
  const uid = encodeURIComponent(String(user.id));
  const msgKey = `msg-${uid}-${encodeURIComponent(String(candidate.id))}`;

  if (origin === "inferred") {
    const created = Date.parse(user.createdAt);
    const profile = Date.parse(user.profileCreatedAt);
    if (!Number.isFinite(created) || !Number.isFinite(profile)) return hold("unknown_user_data");
    // new = account or notification profile younger than the grace period
    if (nowMs - Math.max(created, profile) < NEW_USER_MS) return hold("new_user_no_suggestions");
    if (!gkZoneOk(user.timezone)) return hold("unknown_timezone");
    const cap = config && config.dailyNudgeCap;
    if (!Number.isInteger(cap) || cap < 0) return hold("unknown_cap");
    if (cap === 0) return hold("daily_nudge_cap_reached");
    if (!gkClaim(dir, msgKey)) return hold("already_handled");
    const day = gkDayKey(nowMs, user.timezone);
    const c = gkCount(dir, `nudges-${uid}-${day}`, cap);
    if (!c.ok) {
      gkUnclaim(dir, msgKey);
      return hold("daily_nudge_cap_reached");
    }
    return { send: true, reasonCode: "sent" };
  }

  // requested / reminder: the user asked for them; no cap, no quiet hours
  if (!gkClaim(dir, msgKey)) return hold("already_handled");
  return { send: true, reasonCode: "sent" };
}
EOF
